function shellSort(arr: number[]) {
    let interval = 1;

    while (interval < arr.length / 3) {
        interval = interval * 3 + 1;
    }

    while (interval > 0) {
        for (let outer = interval; outer < arr.length; outer++) {
            const value = arr[outer];
            let inner = outer;

            while (inner > interval - 1 && arr[inner - interval] >= value) {
                arr[inner] = arr[inner - interval];
                inner -= interval;
            }

            arr[inner] = value;
        }
        interval = (interval - 1) / 3;
    }
}

function mergeSort(arr: number[]): number[] {
    // Base case: arrays with 0 or 1 elements are already sorted
    if (arr.length <= 1) {
        return arr;
    }

    // Divide the array into two halves
    const mid = Math.floor(arr.length / 2);
    const left = arr.slice(0, mid);
    const right = arr.slice(mid);

    // Recursively sort both halves and merge them
    return merge(mergeSort(left), mergeSort(right));
}

function merge(left: number[], right: number[]): number[] {
    const result: number[] = [];
    let i = 0;
    let j = 0;

    // Compare elements from both arrays and push the smaller one
    while (i < left.length && j < right.length) {
        if (left[i] <= right[j]) {
            result.push(left[i]);
            i++;
        } else {
            result.push(right[j]);
            j++;
        }
    }

    // Concatenate any remaining elements (one of these loops will run)
    return result.concat(left.slice(i)).concat(right.slice(j));
}

