function heapSort(arr: number[]): number[] {
    const n = arr.length;

    // Step 1: Build the max heap
    // Start from the last non-leaf node and heapify each node upwards
    for (let i = Math.floor(n / 2) - 1; i >= 0; i--) {
        heapify(arr, n, i);
    }

    // Step 2: Extract elements from the heap one by one
    for (let i = n - 1; i > 0; i--) {
        // Move current root (largest element) to the end of the array
        [arr[0], arr[i]] = [arr[i], arr[0]];

        // Call max heapify on the reduced heap to restore the heap property
        heapify(arr, i, 0);
    }

    return arr;
}

function heapify(arr: number[], size: number, rootIdx: number): void {
    let largest = rootIdx;
    const leftIdx = 2 * rootIdx + 1;
    const rightIdx = 2 * rootIdx + 2;

    // If left child is larger than root
    if (leftIdx < size && arr[leftIdx] > arr[largest]) {
        largest = leftIdx;
    }

    // If right child is larger than the largest so far
    if (rightIdx < size && arr[rightIdx] > arr[largest]) {
        largest = rightIdx;
    }

    // If the largest is not the root, swap and continue heapifying down
    if (largest !== rootIdx) {
        [arr[rootIdx], arr[largest]] = [arr[largest], arr[rootIdx]];

        // Recursively heapify the affected sub-tree
        heapify(arr, size, largest);
    }
}

