import java.util.*;

class Stack {
    private int top;
    private int[] stack;
    private int capacity;
    Stack(int size) {
        top = -1;
        capacity = size;
        stack = new int[capacity];
    }
    void push(int x) {
        if (top == capacity - 1) {
            System.out.println("Stack Overflow");
            System.exit(1);
        }
        stack[++top] = x;
    }
    int pop() {
        if (top == -1) {
            System.out.println("Stack Underflow");
            System.exit(1);
        }
        return stack[top--];
    }
}

