        if(!this.root) return false

        let current: Node | null = this.root
        let found: Node | boolean = false
        while(current && !found){
            if(value < current.value){
                current = current.left
            } else if(value > current.value){
                current = current.right
            } else {
                found = current
            }

        }
        if(!found) return undefined;
        return found
    }

