class BinarySearchTree {
public:
    std::shared_ptr<Node> root;
    int nodes;

    BinarySearchTree() : root(nullptr), nodes(0) {}

    BinarySearchTree* insert(int value) {
        auto newNode = std::make_shared<Node>(value);
        if (root == nullptr) {
            root = newNode;
            nodes++;
            return this;
        }
        auto current = root;
        while (current != nullptr) {
            if (value == current->value) return nullptr;
            if (value < current->value) {
                if (current->left == nullptr) {
                    current->left = newNode;
                    nodes++;
                    return this;
                }
                current = current->left;
            } else {
                if (current->right == nullptr) {
                    current->right = newNode;
                    nodes++;
                    return this;
                }
                current = current->right;
            }
        }
        return this;
    }

    std::shared_ptr<Node> find(int value) {
        if (root == nullptr) return nullptr;

        auto current = root;
        std::shared_ptr<Node> found = nullptr;
        while (current != nullptr && found == nullptr) {
            if (value < current->value) {
                current = current->left;
            } else if (value > current->value) {
                current = current->right;
            } else {
                found = current;
            }
        }
        return found;
    }

    void remove(int value) {
        root = removeNode(root, value);
        nodes--;
    }

    std::shared_ptr<Node> removeNode(std::shared_ptr<Node> current, int value) {
        if (current == nullptr) return current;
        if (value == current->value) {
            if (current->left == nullptr && current->right == nullptr) {
                return nullptr;
            } else if (current->left == nullptr) {
                return current->right;
            } else if (current->right == nullptr) {
                return current->left;
            } else {
                auto tempNode = kthSmallestNode(current->right);
                current->value = tempNode->value;
                current->right = removeNode(current->right, tempNode->value);
                return current;
            }
        } else if (value < current->value) {
            current->left = removeNode(current->left, value);
            return current;
        } else {
            current->right = removeNode(current->right, value);
            return current;
        }
    }

    std::shared_ptr<Node> kthSmallestNode(std::shared_ptr<Node> node) {
        while (node->left != nullptr) {
            node = node->left;
        }
        return node;
    }

    void clear() {
        root = nullptr;
        nodes = 0;
    }
};

